+        "3" => Some(data::TRIGRAMS.iter().map(|s| s.to_string()).collect()),
+        "4" => Some(data::TETRAGRAMS.iter().map(|s| s.to_string()).collect()),
+        "w" => Some(data::WORDS.iter().map(|s| s.to_string()).collect()),
+        _ => None,
+    };
+
+    if let Some(list) = builtins {
+        return Ok(list);
+    }
+
+    let path = Path::new(arg);
+    if !path.exists() {
+        eprintln!("File not found: {}", arg);
+        std::process::exit(1);
+    }
+
+    let content = fs::read_to_string(path)?;
+    Ok(content
+        .split(',')
+        .map(|item| item.trim().to_string())
+        .filter(|item| !item.is_empty())
