use std::collections::HashMap;

#[derive(Clone, Copy)]
pub struct Layout {
    pub row1: [&'static str; 12],
    pub row2: [&'static str; 11],
    pub row3: [&'static str; 10],
}

impl Layout {
    pub fn all_keys(&self) -> Vec<&'static str> {
        self.row1
            .iter()
            .chain(self.row2.iter())
            .chain(self.row3.iter())
            .copied()
            .collect()
    }
}

pub const QWERTY: Layout = Layout {
    row1: ["q", "w", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]"],
    row2: ["a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'"],
    row3: ["z", "x", "c", "v", "b", "n", "m", ",", ".", "/"],
};

pub const QWERTZ: Layout = Layout {
    row1: ["q", "w", "e", "r", "t", "z", "u", "i", "o", "p", "ü", "+"],
    row2: ["a", "s", "d", "f", "g", "h", "j", "k", "l", "ö", "ä"],
    row3: ["y", "x", "c", "v", "b", "n", "m", ",", ".", "-"],
};

pub const AZERTY: Layout = Layout {
    row1: ["a", "z", "e", "r", "t", "y", "u", "i", "o", "p", "^", "$"],
    row2: ["q", "s", "d", "f", "g", "h", "j", "k", "l", "m", "ù"],
    row3: ["w", "x", "c", "v", "b", "n", ",", ";", ":", "!"],
};

pub const DVORAK: Layout = Layout {
    row1: ["'", ",", ".", "p", "y", "f", "g", "c", "r", "l", "/", "="],
    row2: ["a", "o", "e", "u", "i", "d", "h", "t", "n", "s", "-"],
    row3: [";", "q", "j", "k", "x", "b", "m", "w", "v", "z"],
};

pub const COLEMAK: Layout = Layout {
    row1: ["q", "w", "f", "p", "g", "j", "l", "u", "y", ";", "[", "]"],
    row2: ["a", "r", "s", "t", "d", "h", "n", "e", "i", "o", "'"],
    row3: ["z", "x", "c", "v", "b", "k", "m", ",", ".", "/"],
};

pub const COLEMAK_DH: Layout = Layout {
    row1: ["q", "w", "f", "p", "b", "j", "l", "u", "y", ";", "[", "]"],
    row2: ["a", "r", "s", "t", "g", "m", "n", "e", "i", "o", "'"],
    row3: ["z", "x", "c", "d", "v", "k", "h", ",", ".", "/"],
};

pub fn from_name(name: &str) -> Option<&'static Layout> {
    match name {
        "qwerty" => Some(&QWERTY),
        "qwertz" => Some(&QWERTZ),
        "azerty" => Some(&AZERTY),
        "dvorak" => Some(&DVORAK),
        "colemak" => Some(&COLEMAK),
        "colemakdh" => Some(&COLEMAK_DH),
        _ => None,
    }
}

pub fn translate_char(input_layout: &Layout, output_layout: &Layout, c: char) -> char {
    if c == ' ' {
        return c;
    }

    let uppercase = c.is_ascii_uppercase();
    let needle = c.to_lowercase().to_string();

    let input_keys = input_layout.all_keys();
    let output_keys = output_layout.all_keys();
    let index_map: HashMap<&str, usize> = input_keys
        .iter()
        .enumerate()
        .map(|(idx, key)| (*key, idx))
        .collect();

    let mapped = index_map
        .get(needle.as_str())
        .and_then(|idx| output_keys.get(*idx))
        .copied()
        .unwrap_or(needle.as_str());

    let mut chars = mapped.chars();
    let first = chars.next().unwrap_or(c);
    if uppercase && first.is_ascii_alphabetic() {
        first.to_ascii_uppercase()
    } else {
        first
    }
}

