mod data;
mod layouts;

use std::fs;
use std::io::{self, Stdout, Write};
use std::path::Path;
use std::time::Instant;

use clap::Parser;
use crossterm::cursor::{Hide, Show};
use crossterm::event::{self, Event, KeyCode, KeyEventKind};
use crossterm::terminal::{self, Clear, ClearType, EnterAlternateScreen, LeaveAlternateScreen};
use crossterm::{execute, queue};
use layouts::{from_name, translate_char, Layout, QWERTY};
use rand::seq::SliceRandom;
use unicode_width::UnicodeWidthStr;

const BOLD: &str = "\x1b[1m";
const ITALIC: &str = "\x1b[3m";
const RESET: &str = "\x1b[0m";

const STAGGERED_TOP: &str = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐";
const STAGGERED_MID_1: &str = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘";
const STAGGERED_MID_2: &str = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘";
const STAGGERED_BOTTOM: &str = "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘";
const ORTHO_TOP: &str = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐";
const ORTHO_MID: &str = "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤";
const ORTHO_BOTTOM: &str = "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘";

#[derive(Parser, Debug)]
#[command(disable_version_flag = true, long_about = None)]
struct Args {
    #[arg(
        short = 'n',
        long = "n",
        default_value = "2",
        value_name = "2|3|4|w|file",
        help = "use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."
    )]
    n: String,

    #[arg(
        short = 't',
        long = "top",
        default_value_t = 50,
        value_name = "1-200",
        help = "use the top X ngrams ordered by usage."
    )]
    top: u16,

    #[arg(
        short = 'c',
        long = "combi",
        default_value_t = 2,
        value_name = "1-200",
        help = "how many different ngrams to use in a single lesson."
    )]
    combi: u16,

    #[arg(
        short = 'r',
        long = "rep",
        default_value_t = 3,
        value_name = "number",
        help = "how often to repeat *each* different ngram in a lesson."
    )]
    rep: u16,

    #[arg(
        short = 'w',
        long = "wpm",
        default_value_t = 40,
        value_name = "number",
        help = "the wpm threshold at which the lesson is considered a success."
    )]
    wpm: u16,

    #[arg(
        short = 'a',
        long = "acc",
        default_value_t = 94,
        value_name = "0-100",
        help = "the accuracy in percent at which the lesson is considered a success."
    )]
    acc: u16,

    #[arg(
        long = "emu-in",
        default_value = "",
        value_name = "layout",
        help = "your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."
    )]
    emu_in: String,

    #[arg(
        long = "emu-out",
        default_value = "",
        value_name = "layout",
        help = "the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."
    )]
    emu_out: String,

    #[arg(long = "show-ortho", help = "show keyboard in ortholinear format")]
    show_ortho: bool,

    #[arg(long = "nokb", help = "pass this flag to disable the keyboard layout display.")]
    nokb: bool,

    #[arg(long = "cat", help = "the most important flag. don't practice alone.")]
    cat: bool,
}

#[derive(Clone)]
struct Config {
    ngrams: Vec<String>,
    top: usize,
    combi: usize,
    rep: usize,
    target_wpm: u16,
    target_acc: u16,
    show_keyboard: bool,
    show_ortho: bool,
    show_cat: bool,
    emu_in: Layout,
    emu_out: Layout,
}

struct Game {
    config: Config,
    lesson_number: u64,
    success_count: u64,
    failure_count: u64,
    total_wpm: u64,
    total_acc: u64,
    last_wpm: u64,
    last_acc: u64,
    lesson: String,
    typed: String,
    wrong_keys: u64,
    actions: u64,
    started_at: Option<Instant>,
}

fn main() -> io::Result<()> {
    let args = Args::parse();

    if args.emu_in.is_empty() ^ args.emu_out.is_empty() {
        eprintln!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }

    validate_range("top", args.top, 1, 200);
    validate_range("combi", args.combi, 1, 200);
    validate_range("rep", args.rep, 1, 200);
    validate_range("wpm", args.wpm, 1, 200);
    validate_range("acc", args.acc, 0, 100);

    let ngrams = load_lessons(&args.n)?;
    let config = Config {
        ngrams,
        top: args.top as usize,
        combi: args.combi as usize,
        rep: args.rep as usize,
        target_wpm: args.wpm,
        target_acc: args.acc,
        show_keyboard: !args.nokb,
        show_ortho: args.show_ortho,
        show_cat: args.cat,
        emu_in: *from_name(&args.emu_in).unwrap_or(&QWERTY),
        emu_out: *from_name(&args.emu_out).unwrap_or(&QWERTY),
    };

    let mut game = Game::new(config);
    enter_tui()?;
    game.run()?;
    leave_tui()?;
    Ok(())
}

fn validate_range(name: &str, value: u16, min: u16, max: u16) {
    if value < min || value > max {
        eprintln!(
            "Invalid argument for {}. Use a number between {} and {}.",
            name, min, max
        );
        std::process::exit(1);
    }
}

fn load_lessons(arg: &str) -> io::Result<Vec<String>> {
    let builtins = match arg {
        "2" => Some(data::BIGRAMS.iter().map(|s| s.to_string()).collect()),
        "3" => Some(data::TRIGRAMS.iter().map(|s| s.to_string()).collect()),
        "4" => Some(data::TETRAGRAMS.iter().map(|s| s.to_string()).collect()),
        "w" => Some(data::WORDS.iter().map(|s| s.to_string()).collect()),
        _ => None,
    };

    if let Some(list) = builtins {
        return Ok(list);
    }

    let path = Path::new(arg);
    if !path.exists() {
        eprintln!("File not found: {}", arg);
        std::process::exit(1);
    }

    let content = fs::read_to_string(path)?;
    Ok(content
        .split(',')
        .map(|item| item.trim().to_string())
        .filter(|item| !item.is_empty())
        .collect())
}

fn enter_tui() -> io::Result<()> {
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, Clear(ClearType::All), Hide)?;
    terminal::enable_raw_mode()?;
    Ok(())
}

fn leave_tui() -> io::Result<()> {
    let mut stdout = io::stdout();
    terminal::disable_raw_mode()?;
    execute!(stdout, Show, LeaveAlternateScreen)?;
    Ok(())
}

impl Game {
    fn new(config: Config) -> Self {
        let mut game = Self {
            config,
            lesson_number: 0,
            success_count: 0,
            failure_count: 0,
            total_wpm: 0,
            total_acc: 0,
            last_wpm: 0,
            last_acc: 0,
            lesson: String::new(),
            typed: String::new(),
            wrong_keys: 0,
            actions: 0,
            started_at: None,
        };
        game.next_lesson();
        game
    }

    fn run(&mut self) -> io::Result<()> {
        let mut stdout = io::stdout();
        self.render(&mut stdout)?;

        loop {
            match event::read()? {
                Event::Key(key) if key.kind == KeyEventKind::Press || key.kind == KeyEventKind::Repeat => {
                    match key.code {
                        KeyCode::Esc => break,
                        KeyCode::Backspace => {
                            if !self.typed.is_empty() {
                                self.typed.pop();
                                self.actions += 1;
                                self.render(&mut stdout)?;
                            }
                        }
                        KeyCode::Char(mut c) => {
                            if self.typed.chars().count() >= self.lesson.chars().count() {
                                continue;
                            }
                            if c.is_ascii_alphabetic() && key.modifiers.is_empty() {
                                c = c.to_ascii_lowercase();
                            }
                            let mapped = translate_char(&self.config.emu_in, &self.config.emu_out, c);
                            if self.started_at.is_none() {
                                self.started_at = Some(Instant::now());
                            }
                            let index = self.typed.chars().count();
                            let expected = nth_char(&self.lesson, index);
                            self.typed.push(mapped);
                            self.actions += 1;
                            if expected != Some(mapped) {
                                self.wrong_keys += 1;
                            }
                            if self.typed == self.lesson {
                                self.finish_lesson();
                            }
                            self.render(&mut stdout)?;
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }

        Ok(())
    }

    fn next_lesson(&mut self) {
        self.lesson_number += 1;
        self.lesson = self.build_lesson();
        self.typed.clear();
        self.wrong_keys = 0;
        self.actions = 0;
        self.started_at = None;
    }

    fn build_lesson(&self) -> String {
        let mut rng = rand::thread_rng();
        let limit = self.config.top.min(self.config.ngrams.len());
        let available = &self.config.ngrams[..limit];
        let picks: Vec<String> = (0..self.config.combi)
            .map(|_| available.choose(&mut rng).unwrap().clone())
            .collect();
        let chunk = picks.join(" ");
        let mut lesson = std::iter::repeat(chunk)
            .take(self.config.rep)
            .collect::<Vec<_>>()
            .join(" ");
        lesson.push(' ');
        lesson
    }

    fn finish_lesson(&mut self) {
        let started_at = self.started_at.unwrap_or_else(Instant::now);
        let elapsed = started_at.elapsed().as_secs_f64().max(f64::EPSILON);
        let non_space = self.lesson.chars().filter(|c| *c != ' ').count() as f64;
        let wpm = ((non_space / 5.0) / (elapsed / 60.0)).floor() as u64;
        let acc = if self.actions == 0 {
            0
        } else {
            ((self.actions.saturating_sub(self.wrong_keys)) * 100 / self.actions) as u64
        };

        self.last_wpm = wpm;
        self.last_acc = acc;
        self.total_wpm += wpm;
        self.total_acc += acc;

        if wpm >= self.config.target_wpm as u64 && acc >= self.config.target_acc as u64 {
            self.success_count += 1;
        } else {
            self.failure_count += 1;
        }

        self.next_lesson();
    }

    fn avg_wpm(&self) -> u64 {
        let completed = self.success_count + self.failure_count;
        if completed == 0 {
            0
        } else {
            self.total_wpm / completed
        }
    }

    fn avg_acc(&self) -> u64 {
        let completed = self.success_count + self.failure_count;
        if completed == 0 {
            0
        } else {
            self.total_acc / completed
        }
    }

    fn render(&self, stdout: &mut Stdout) -> io::Result<()> {
        let (cols, rows) = terminal::size()?;
        let inner_width = cols.saturating_sub(2) as usize;
        let mut lines = Vec::new();

        lines.push(render_top_border(inner_width));
        lines.push(render_header(inner_width));
        lines.push(render_separator(inner_width));
        lines.push(render_status_line(
            inner_width,
            self.lesson_number,
            self.success_count,
            self.failure_count,
        ));
        lines.push(render_separator(inner_width));
        lines.push(blank_line(inner_width));
        lines.push(render_prompt_line(inner_width, &self.lesson, &self.typed));
        lines.push(render_error_line(inner_width, &self.lesson, &self.typed));

        if self.config.show_keyboard {
            let keyboard_lines = render_keyboard(
                &self.config.emu_out,
                self.config.show_ortho,
                self.config.show_cat,
                inner_width,
            );
            lines.extend(keyboard_lines);

            if self.config.show_cat {
                lines.push(render_cat_separator(inner_width));
                lines.push(render_metric_line_with_suffix(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                    "                       \\\\      ",
                ));
                lines.push(render_acc_line_with_suffix(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                    "                        V      ",
                ));
            } else {
                lines.push(render_separator(inner_width));
                lines.push(render_metric_line(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                ));
                lines.push(render_acc_line(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                ));
            }
        } else {
            lines.push(blank_line(inner_width));
            lines.push(render_separator(inner_width));
            if self.config.show_cat {
                lines.push(render_metric_line_with_suffix(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                    "                 /\\_/\\\\        ",
                ));
                lines.push(render_acc_line_with_suffix(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                    "                >(•༝• )<      ",
                ));
            } else {
                lines.push(render_metric_line(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                ));
                lines.push(render_acc_line(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                ));
            }
        }

        let bottom = if self.config.show_cat && !self.config.show_keyboard {
            render_bottom_border_with_suffix(inner_width, "    |    \\───────")
        } else {
            render_bottom_border(inner_width)
        };
        lines.push(bottom);

        while lines.len() < rows as usize {
            lines.push(String::new());
        }

        queue!(stdout, crossterm::cursor::MoveTo(0, 0), Clear(ClearType::All))?;
        for (idx, line) in lines.iter().enumerate() {
            if idx > 0 {
                write!(stdout, "\r\n")?;
            }
            write!(stdout, "{}", line)?;
        }
        stdout.flush()?;
        Ok(())
    }
}

fn nth_char(s: &str, idx: usize) -> Option<char> {
    s.chars().nth(idx)
}

fn blank_line(inner_width: usize) -> String {
    format!("│{}│", " ".repeat(inner_width))
}

fn render_top_border(inner_width: usize) -> String {
    let title = " Quit <esc> ";
    format!(
        "╭{}{}╮",
        "─".repeat(inner_width.saturating_sub(title.len())),
        title
    )
}

fn render_bottom_border(inner_width: usize) -> String {
    format!("╰{}╯", "─".repeat(inner_width))
}

fn render_bottom_border_with_suffix(inner_width: usize, suffix: &str) -> String {
    let suffix_width = UnicodeWidthStr::width(suffix);
    let fill = inner_width.saturating_sub(suffix_width);
    format!("╰{}{}╯", "─".repeat(fill), suffix)
}

fn render_separator(inner_width: usize) -> String {
    format!("│{}│", "─".repeat(inner_width))
}

fn render_cat_separator(inner_width: usize) -> String {
    let suffix = "/▔▔▔▔▔▔▔▔||▔▔\\───";
    let fill = inner_width.saturating_sub(UnicodeWidthStr::width(suffix));
    format!("│{}{}│", "─".repeat(fill), suffix)
}

fn render_header(inner_width: usize) -> String {
    let plain = "ngrrram!   by winterveil";
    let left = inner_width.saturating_sub(UnicodeWidthStr::width(plain)) / 2;
    let right = inner_width.saturating_sub(left + UnicodeWidthStr::width(plain));
    format!(
        "│{}{}ngrrram!{}   by winterveil{}│",
        " ".repeat(left),
        BOLD,
        RESET,
        " ".repeat(right)
    )
}

fn render_status_line(inner_width: usize, lesson: u64, success: u64, failure: u64) -> String {
    let left = format!("    Lesson #{}", lesson);
    let right = format!("✔: {}, ✘: {}    ", success, failure);
    let gap = inner_width.saturating_sub(UnicodeWidthStr::width(left.as_str()) + UnicodeWidthStr::width(right.as_str()));
    format!("│{}{}{}│", left, " ".repeat(gap), right)
}

fn render_prompt_line(inner_width: usize, lesson: &str, typed: &str) -> String {
    let lesson_width = UnicodeWidthStr::width(lesson);
    let left = inner_width.saturating_sub(lesson_width) / 2;
    let right = inner_width.saturating_sub(left + lesson_width);
    let typed_len = typed.chars().count().min(lesson.chars().count());
    let consumed: String = lesson.chars().take(typed_len).collect();
    let remaining: String = lesson.chars().skip(typed_len).collect();
    format!(
        "│{}{}{}{}{}│",
        " ".repeat(left),
        consumed,
        if remaining.is_empty() {
            String::new()
        } else {
            format!("{}{}{}", BOLD, remaining, RESET)
        },
        "",
        " ".repeat(right)
    )
}

fn render_error_line(inner_width: usize, lesson: &str, typed: &str) -> String {
    let correct = typed
        .chars()
        .zip(lesson.chars())
        .take_while(|(a, b)| a == b)
        .count();
    let suffix: String = typed.chars().skip(correct).collect();
    if suffix.is_empty() {
        return blank_line(inner_width);
    }
    let width = UnicodeWidthStr::width(suffix.as_str());
    let left = inner_width.saturating_sub(width) / 2;
    let right = inner_width.saturating_sub(left + width);
    format!(
        "│{}{}{}{}{}│",
        " ".repeat(left),
        ITALIC,
        suffix,
        RESET,
        " ".repeat(right)
    )
}

fn render_metric_line(inner_width: usize, target: u16, avg: u64, last: u64) -> String {
    format_metric_line(inner_width, target, avg, last, None)
}

fn render_metric_line_with_suffix(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: &str,
) -> String {
    format_metric_line(inner_width, target, avg, last, Some(suffix))
}

fn render_acc_line(inner_width: usize, target: u16, avg: u64, last: u64) -> String {
    format_acc_line(inner_width, target, avg, last, None)
}

fn render_acc_line_with_suffix(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: &str,
) -> String {
    format_acc_line(inner_width, target, avg, last, Some(suffix))
}

fn format_metric_line(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: Option<&str>,
) -> String {
    let base = format!(
        "  need >= {:>3}WPM,   avg. {:>3}WPM,   last{:>4}WPM",
        target, avg, last
    );
    wrap_inner(inner_width, &base, suffix)
}

fn format_acc_line(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: Option<&str>,
) -> String {
    let base = format!(
        "  need >= {:>3}% Acc, avg. {:>3}% Acc, last{:>4}% Acc",
        target, avg, last
    );
    wrap_inner(inner_width, &base, suffix)
}

fn wrap_inner(inner_width: usize, left_text: &str, suffix: Option<&str>) -> String {
    match suffix {
        Some(suffix) => {
            let used = UnicodeWidthStr::width(left_text) + UnicodeWidthStr::width(suffix);
            let gap = inner_width.saturating_sub(used);
            format!("│{}{}{}│", left_text, " ".repeat(gap), suffix)
        }
        None => {
            let gap = inner_width.saturating_sub(UnicodeWidthStr::width(left_text));
            format!("│{}{}│", left_text, " ".repeat(gap))
        }
    }
}

fn render_keyboard(layout: &Layout, ortho: bool, cat: bool, inner_width: usize) -> Vec<String> {
    let rows = if ortho {
        render_ortho_keyboard(layout)
    } else {
        render_staggered_keyboard(layout)
    };

    let left_pad = if cat { 5 } else { 0 };
    rows.into_iter()
        .enumerate()
        .map(|(idx, row)| {
            let content = if cat {
                let suffix = match idx {
                    2 => Some("          /\\_/\\\\        "),
                    3 => Some("        >(•༝• )<      "),
                    4 => Some("         |    \\       "),
                    5 => Some("          || |  )      "),
                    6 => Some("          ll-l-//      "),
                    _ => None,
                };
                let prefix = format!("{}{}", " ".repeat(left_pad), row);
                wrap_inner(inner_width, &prefix, suffix)
            } else {
                let row_width = UnicodeWidthStr::width(row.as_str());
                let pad = inner_width.saturating_sub(row_width) / 2;
                let right = inner_width.saturating_sub(pad + row_width);
                format!("│{}{}{}│", " ".repeat(pad), row, " ".repeat(right))
            };
            content
        })
        .collect()
}

fn render_staggered_keyboard(layout: &Layout) -> Vec<String> {
    vec![
        STAGGERED_TOP.to_string(),
        format!("│ {} │", layout.row1.join(" │ ")),
        STAGGERED_MID_1.to_string(),
        format!(" │ {} │", layout.row2.join(" │ ")),
        format!(" {}", STAGGERED_MID_2),
        format!("  │ {} │", layout.row3.join(" │ ")),
        format!("  {}", STAGGERED_BOTTOM),
    ]
}

fn render_ortho_keyboard(layout: &Layout) -> Vec<String> {
    let mut row2: Vec<&str> = layout.row2.to_vec();
    row2.push("△");
    let mut row3: Vec<&str> = layout.row3.to_vec();
    row3.push("△");
    row3.push("△");

    vec![
        ORTHO_TOP.to_string(),
        format!("│ {} │", layout.row1.join(" │ ")),
        ORTHO_MID.to_string(),
        format!("│ {} │", row2.join(" │ ")),
        ORTHO_MID.to_string(),
        format!("│ {} │", row3.join(" │ ")),
        ORTHO_BOTTOM.to_string(),
    ]
}

