mod data;
mod layouts;

use std::env;
use std::fs;
use std::fs::OpenOptions;
use std::io::{self, Read, Stdout, Write};
use std::mem::zeroed;
use std::os::fd::AsRawFd;
use std::path::Path;
use std::time::Instant;

use layouts::{from_name, translate_char, Layout, QWERTY};

const BOLD: &str = "\x1b[1m";
const ITALIC: &str = "\x1b[3m";
const RESET: &str = "\x1b[0m";

const STAGGERED_TOP: &str = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐";
const STAGGERED_MID_1: &str = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘";
const STAGGERED_MID_2: &str = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘";
const STAGGERED_BOTTOM: &str = "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘";
const ORTHO_TOP: &str = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐";
const ORTHO_MID: &str = "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤";
const ORTHO_BOTTOM: &str = "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘";

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

unsafe extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TCSANOW: i32 = 0;
const BRKINT: u32 = 0o000002;
const ICRNL: u32 = 0o000400;
const INPCK: u32 = 0o000020;
const ISTRIP: u32 = 0o000040;
const IXON: u32 = 0o002000;
const OPOST: u32 = 0o000001;
const CS8: u32 = 0o000060;
const ECHO: u32 = 0o000010;
const ICANON: u32 = 0o000002;
const IEXTEN: u32 = 0o100000;
const ISIG: u32 = 0o000001;
const VTIME: usize = 5;
const VMIN: usize = 6;
const TIOCGWINSZ: u64 = 0x5413;

#[derive(Debug, Clone)]
struct Args {
    n: String,
    top: u16,
    combi: u16,
    rep: u16,
    wpm: u16,
    acc: u16,
    emu_in: String,
    emu_out: String,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
}

#[derive(Clone)]
struct Config {
    ngrams: Vec<String>,
    top: usize,
    combi: usize,
    rep: usize,
    target_wpm: u16,
    target_acc: u16,
    show_keyboard: bool,
    show_ortho: bool,
    show_cat: bool,
    emu_in: Layout,
    emu_out: Layout,
}

struct TtyState {
    tty: fs::File,
    original: Termios,
}

#[derive(Clone)]
struct SimpleRng {
    state: u64,
}

struct Game {
    config: Config,
    tty: TtyState,
    rng: SimpleRng,
    lesson_number: u64,
    success_count: u64,
    failure_count: u64,
    total_wpm: u64,
    total_acc: u64,
    last_wpm: u64,
    last_acc: u64,
    lesson: String,
    typed: String,
    wrong_keys: u64,
    actions: u64,
    started_at: Option<Instant>,
}

enum Key {
    Esc,
    Backspace,
    Char(char),
    Other,
}

fn main() -> io::Result<()> {
    let argv: Vec<String> = env::args().collect();
    let program = program_name(&argv);
    let args = parse_args(&argv[1..], &program);

    if args.emu_in.is_empty() ^ args.emu_out.is_empty() {
        eprintln!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }

    validate_range("top", args.top, 1, 200);
    validate_range("combi", args.combi, 1, 200);
    validate_range("rep", args.rep, 1, 200);
    validate_range("wpm", args.wpm, 1, 200);
    validate_range("acc", args.acc, 0, 100);

    let ngrams = load_lessons(&args.n)?;
    let config = Config {
        ngrams,
        top: args.top as usize,
        combi: args.combi as usize,
        rep: args.rep as usize,
        target_wpm: args.wpm,
        target_acc: args.acc,
        show_keyboard: !args.nokb,
        show_ortho: args.show_ortho,
        show_cat: args.cat,
        emu_in: *from_name(&args.emu_in).unwrap_or(&QWERTY),
        emu_out: *from_name(&args.emu_out).unwrap_or(&QWERTY),
    };

    let tty = enter_tui()?;
    let mut game = Game::new(config, tty);
    game.run()?;
    leave_tui(&game.tty)?;
    Ok(())
}

fn program_name(argv: &[String]) -> String {
    argv.first()
        .and_then(|arg| Path::new(arg).file_name())
        .and_then(|name| name.to_str())
        .unwrap_or("executable")
        .to_string()
}

fn help_text(program: &str) -> String {
    format!(
        "Usage: {program} [OPTIONS]\n\nOptions:\n  -n, --n <2|3|4|w|file>  use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file. [default: 2]\n  -t, --top <1-200>       use the top X ngrams ordered by usage. [default: 50]\n  -c, --combi <1-200>     how many different ngrams to use in a single lesson. [default: 2]\n  -r, --rep <number>      how often to repeat *each* different ngram in a lesson. [default: 3]\n  -w, --wpm <number>      the wpm threshold at which the lesson is considered a success. [default: 40]\n  -a, --acc <0-100>       the accuracy in percent at which the lesson is considered a success. [default: 94]\n      --emu-in <layout>   your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --emu-out <layout>  the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --show-ortho        show keyboard in ortholinear format\n      --nokb              pass this flag to disable the keyboard layout display.\n      --cat               the most important flag. don't practice alone.\n  -h, --help              Print help\n"
    )
}

fn parse_args(raw: &[String], program: &str) -> Args {
    let mut args = Args {
        n: "2".to_string(),
        top: 50,
        combi: 2,
        rep: 3,
        wpm: 40,
        acc: 94,
        emu_in: String::new(),
        emu_out: String::new(),
        show_ortho: false,
        nokb: false,
        cat: false,
    };

    let mut i = 0;
    while i < raw.len() {
        let arg = &raw[i];

        if let Some(value) = arg.strip_prefix("--n=") {
            args.n = value.to_string();
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--top=") {
            args.top = parse_numeric_value(value, "--top <1-200>");
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--combi=") {
            args.combi = parse_numeric_value(value, "--combi <1-200>");
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--rep=") {
            args.rep = parse_numeric_value(value, "--rep <number>");
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--wpm=") {
            args.wpm = parse_numeric_value(value, "--wpm <number>");
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--acc=") {
            args.acc = parse_numeric_value(value, "--acc <0-100>");
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--emu-in=") {
            args.emu_in = value.to_string();
            i += 1;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--emu-out=") {
            args.emu_out = value.to_string();
            i += 1;
            continue;
        }

        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", help_text(program));
                std::process::exit(0);
            }
            "-n" | "--n" => {
                i += 1;
                args.n = required_value(raw, i, "--n <2|3|4|w|file>", program).to_string();
            }
            "-t" | "--top" => {
                i += 1;
                args.top = parse_numeric_arg(raw, i, "--top <1-200>", program);
            }
            "-c" | "--combi" => {
                i += 1;
                args.combi = parse_numeric_arg(raw, i, "--combi <1-200>", program);
            }
            "-r" | "--rep" => {
                i += 1;
                args.rep = parse_numeric_arg(raw, i, "--rep <number>", program);
            }
            "-w" | "--wpm" => {
                i += 1;
                args.wpm = parse_numeric_arg(raw, i, "--wpm <number>", program);
            }
            "-a" | "--acc" => {
                i += 1;
                args.acc = parse_numeric_arg(raw, i, "--acc <0-100>", program);
            }
            "--emu-in" => {
                i += 1;
                args.emu_in = required_value(raw, i, "--emu-in <layout>", program).to_string();
            }
            "--emu-out" => {
                i += 1;
                args.emu_out = required_value(raw, i, "--emu-out <layout>", program).to_string();
            }
            "--show-ortho" => args.show_ortho = true,
            "--nokb" => args.nokb = true,
            "--cat" => args.cat = true,
            _ => unexpected_argument(arg, program),
        }
        i += 1;
    }

    args
}

fn required_value<'a>(raw: &'a [String], index: usize, flag: &str, program: &str) -> &'a str {
    match raw.get(index) {
        Some(value) if !value.starts_with('-') || value == "-" => value.as_str(),
        Some(value) => unexpected_argument(value, program),
        None => {
            eprintln!("error: a value is required for '{flag}' but none was supplied");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

fn parse_numeric_arg(raw: &[String], index: usize, display: &str, program: &str) -> u16 {
    let value = required_value(raw, index, display, program);
    parse_numeric_value(value, display)
}

fn parse_numeric_value(value: &str, display: &str) -> u16 {
    match value.parse::<u16>() {
        Ok(parsed) => parsed,
        Err(err) => {
            eprintln!(
                "error: invalid value '{}' for '{}': {}",
                value, display, err
            );
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

fn unexpected_argument(arg: &str, program: &str) -> ! {
    eprintln!("error: unexpected argument '{}' found", arg);
    eprintln!();
    eprintln!("Usage: {} [OPTIONS]", program);
    eprintln!();
    eprintln!("For more information, try '--help'.");
    std::process::exit(2);
}

fn validate_range(name: &str, value: u16, min: u16, max: u16) {
    if value < min || value > max {
        eprintln!(
            "Invalid argument for {}. Use a number between {} and {}.",
            name, min, max
        );
        std::process::exit(1);
    }
}

fn load_lessons(arg: &str) -> io::Result<Vec<String>> {
    let builtins = match arg {
        "2" => Some(data::BIGRAMS.iter().map(|s| s.to_string()).collect()),
        "3" => Some(data::TRIGRAMS.iter().map(|s| s.to_string()).collect()),
        "4" => Some(data::TETRAGRAMS.iter().map(|s| s.to_string()).collect()),
        "w" => Some(data::WORDS.iter().map(|s| s.to_string()).collect()),
        _ => None,
    };

    if let Some(list) = builtins {
        return Ok(list);
    }

    let path = Path::new(arg);
    if !path.exists() {
        eprintln!("File not found: {}", arg);
        std::process::exit(1);
    }

    let content = fs::read_to_string(path)?;
    Ok(content
        .split(',')
        .map(|item| item.trim().to_string())
        .filter(|item| !item.is_empty())
        .collect())
}

fn enter_tui() -> io::Result<TtyState> {
    let mut stdout = io::stdout();
    write!(stdout, "\x1b[?1049h\x1b[2J\x1b[?25l")?;
    stdout.flush()?;

    let tty = OpenOptions::new().read(true).write(true).open("/dev/tty")?;
    let fd = tty.as_raw_fd();
    let mut original: Termios = unsafe { zeroed() };
    cvt(unsafe { tcgetattr(fd, &mut original as *mut _) })?;

    let mut raw = original;
    raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
    raw.c_oflag &= !OPOST;
    raw.c_cflag |= CS8;
    raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    cvt(unsafe { tcsetattr(fd, TCSANOW, &raw as *const _) })?;

    Ok(TtyState { tty, original })
}

fn leave_tui(state: &TtyState) -> io::Result<()> {
    let fd = state.tty.as_raw_fd();
    cvt(unsafe { tcsetattr(fd, TCSANOW, &state.original as *const _) })?;

    let mut stdout = io::stdout();
    write!(stdout, "\x1b[?25h\x1b[?1049l")?;
    stdout.flush()?;
    Ok(())
}

impl Game {
    fn new(config: Config, tty: TtyState) -> Self {
        let mut game = Self {
            config,
            tty,
            rng: SimpleRng::new(),
            lesson_number: 0,
            success_count: 0,
            failure_count: 0,
            total_wpm: 0,
            total_acc: 0,
            last_wpm: 0,
            last_acc: 0,
            lesson: String::new(),
            typed: String::new(),
            wrong_keys: 0,
            actions: 0,
            started_at: None,
        };
        game.next_lesson();
        game
    }

    fn run(&mut self) -> io::Result<()> {
        let mut stdout = io::stdout();
        self.render(&mut stdout)?;

        loop {
            match self.read_key()? {
                Key::Esc => break,
                Key::Backspace => {
                    if !self.typed.is_empty() {
                        self.typed.pop();
                        self.actions += 1;
                        self.render(&mut stdout)?;
                    }
                }
                Key::Char(c) => {
                    if self.typed.chars().count() >= self.lesson.chars().count() {
                        continue;
                    }

                    let mapped = translate_char(&self.config.emu_in, &self.config.emu_out, c);
                    if self.started_at.is_none() {
                        self.started_at = Some(Instant::now());
                    }

                    let index = self.typed.chars().count();
                    let expected = nth_char(&self.lesson, index);
                    self.typed.push(mapped);
                    self.actions += 1;

                    if expected != Some(mapped) {
                        self.wrong_keys += 1;
                    }
                    if self.typed == self.lesson {
                        self.finish_lesson();
                    }

                    self.render(&mut stdout)?;
                }
                Key::Other => {}
            }
        }

        Ok(())
    }

    fn read_key(&mut self) -> io::Result<Key> {
        let mut buf = [0u8; 1];
        self.tty.tty.read_exact(&mut buf)?;
        match buf[0] {
            0x1b => Ok(Key::Esc),
            0x7f | 0x08 => Ok(Key::Backspace),
            b'\r' | b'\n' => Ok(Key::Other),
            byte if byte.is_ascii() => Ok(Key::Char(byte as char)),
            _ => Ok(Key::Other),
        }
    }

    fn terminal_size(&self) -> (u16, u16) {
        let fd = self.tty.tty.as_raw_fd();
        let mut ws: Winsize = unsafe { zeroed() };
        if cvt(unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut _) }).is_ok()
            && ws.ws_col > 0
            && ws.ws_row > 0
        {
            (ws.ws_col, ws.ws_row)
        } else {
            (80, 24)
        }
    }

    fn next_lesson(&mut self) {
        self.lesson_number += 1;
        self.lesson = self.build_lesson();
        self.typed.clear();
        self.wrong_keys = 0;
        self.actions = 0;
        self.started_at = None;
    }

    fn build_lesson(&mut self) -> String {
        let limit = self.config.top.min(self.config.ngrams.len());
        let available = &self.config.ngrams[..limit];
        let picks: Vec<String> = (0..self.config.combi)
            .map(|_| self.rng.choose(available).unwrap().clone())
            .collect();
        let chunk = picks.join(" ");
        let mut lesson = std::iter::repeat(chunk)
            .take(self.config.rep)
            .collect::<Vec<_>>()
            .join(" ");
        lesson.push(' ');
        lesson
    }

    fn finish_lesson(&mut self) {
        let started_at = self.started_at.unwrap_or_else(Instant::now);
        let elapsed = started_at.elapsed().as_secs_f64().max(f64::EPSILON);
        let non_space = self.lesson.chars().filter(|c| *c != ' ').count() as f64;
        let wpm = ((non_space / 5.0) / (elapsed / 60.0)).floor() as u64;
        let acc = if self.actions == 0 {
            0
        } else {
            ((self.actions.saturating_sub(self.wrong_keys)) * 100 / self.actions) as u64
        };

        self.last_wpm = wpm;
        self.last_acc = acc;
        self.total_wpm += wpm;
        self.total_acc += acc;

        if wpm >= self.config.target_wpm as u64 && acc >= self.config.target_acc as u64 {
            self.success_count += 1;
        } else {
            self.failure_count += 1;
        }

        self.next_lesson();
    }

    fn avg_wpm(&self) -> u64 {
        let completed = self.success_count + self.failure_count;
        if completed == 0 {
            0
        } else {
            self.total_wpm / completed
        }
    }

    fn avg_acc(&self) -> u64 {
        let completed = self.success_count + self.failure_count;
        if completed == 0 {
            0
        } else {
            self.total_acc / completed
        }
    }

    fn render(&self, stdout: &mut Stdout) -> io::Result<()> {
        let (cols, rows) = self.terminal_size();
        let inner_width = cols.saturating_sub(2) as usize;
        let mut lines = Vec::new();

        lines.push(render_top_border(inner_width));
        lines.push(render_header(inner_width));
        lines.push(render_separator(inner_width));
        lines.push(render_status_line(
            inner_width,
            self.lesson_number,
            self.success_count,
            self.failure_count,
        ));
        lines.push(render_separator(inner_width));
        lines.push(blank_line(inner_width));
        lines.push(render_prompt_line(inner_width, &self.lesson, &self.typed));
        lines.push(render_error_line(inner_width, &self.lesson, &self.typed));

        if self.config.show_keyboard {
            let keyboard_lines = render_keyboard(
                &self.config.emu_out,
                self.config.show_ortho,
                self.config.show_cat,
                inner_width,
            );
            lines.extend(keyboard_lines);

            if self.config.show_cat {
                lines.push(render_cat_separator(inner_width));
                lines.push(render_metric_line_with_suffix(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                    "                       \\\\      ",
                ));
                lines.push(render_acc_line_with_suffix(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                    "                        V      ",
                ));
            } else {
                lines.push(render_separator(inner_width));
                lines.push(render_metric_line(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                ));
                lines.push(render_acc_line(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                ));
            }
        } else {
            lines.push(blank_line(inner_width));
            lines.push(render_separator(inner_width));
            if self.config.show_cat {
                lines.push(render_metric_line_with_suffix(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                    "                 /\\_/\\\\        ",
                ));
                lines.push(render_acc_line_with_suffix(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                    "                >(•༝• )<      ",
                ));
            } else {
                lines.push(render_metric_line(
                    inner_width,
                    self.config.target_wpm,
                    self.avg_wpm(),
                    self.last_wpm,
                ));
                lines.push(render_acc_line(
                    inner_width,
                    self.config.target_acc,
                    self.avg_acc(),
                    self.last_acc,
                ));
            }
        }

        let bottom = if self.config.show_cat && !self.config.show_keyboard {
            render_bottom_border_with_suffix(inner_width, "    |    \\───────")
        } else {
            render_bottom_border(inner_width)
        };
        lines.push(bottom);

        while lines.len() < rows as usize {
            lines.push(String::new());
        }

        write!(stdout, "\x1b[H\x1b[2J")?;
        for (idx, line) in lines.iter().enumerate() {
            if idx > 0 {
                write!(stdout, "\r\n")?;
            }
            write!(stdout, "{}", line)?;
        }
        stdout.flush()?;
        Ok(())
    }
}

impl SimpleRng {
    fn new() -> Self {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        let pid = std::process::id() as u64;
        Self {
            state: nanos ^ (pid << 16) ^ 0x9e37_79b9_7f4a_7c15,
        }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state = x;
        x
    }

    fn choose<'a, T>(&mut self, items: &'a [T]) -> Option<&'a T> {
        if items.is_empty() {
            None
        } else {
            let index = (self.next_u64() % items.len() as u64) as usize;
            items.get(index)
        }
    }
}

fn cvt(code: i32) -> io::Result<()> {
    if code == -1 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

fn nth_char(s: &str, idx: usize) -> Option<char> {
    s.chars().nth(idx)
}

fn display_width(s: &str) -> usize {
    s.chars().count()
}

fn blank_line(inner_width: usize) -> String {
    format!("│{}│", " ".repeat(inner_width))
}

fn render_top_border(inner_width: usize) -> String {
    let title = " Quit <esc> ";
    format!(
        "╭{}{}╮",
        "─".repeat(inner_width.saturating_sub(title.len())),
        title
    )
}

fn render_bottom_border(inner_width: usize) -> String {
    format!("╰{}╯", "─".repeat(inner_width))
}

fn render_bottom_border_with_suffix(inner_width: usize, suffix: &str) -> String {
    let suffix_width = display_width(suffix);
    let fill = inner_width.saturating_sub(suffix_width);
    format!("╰{}{}╯", "─".repeat(fill), suffix)
}

fn render_separator(inner_width: usize) -> String {
    format!("│{}│", "─".repeat(inner_width))
}

fn render_cat_separator(inner_width: usize) -> String {
    let suffix = "/▔▔▔▔▔▔▔▔||▔▔\\───";
    let fill = inner_width.saturating_sub(display_width(suffix));
    format!("│{}{}│", "─".repeat(fill), suffix)
}

fn render_header(inner_width: usize) -> String {
    let plain = "ngrrram!   by winterveil";
    let left = inner_width.saturating_sub(display_width(plain)) / 2;
    let right = inner_width.saturating_sub(left + display_width(plain));
    format!(
        "│{}{}ngrrram!{}   by winterveil{}│",
        " ".repeat(left),
        BOLD,
        RESET,
        " ".repeat(right)
    )
}

fn render_status_line(inner_width: usize, lesson: u64, success: u64, failure: u64) -> String {
    let left = format!("    Lesson #{}", lesson);
    let right = format!("✔: {}, ✘: {}    ", success, failure);
    let gap = inner_width.saturating_sub(display_width(&left) + display_width(&right));
    format!("│{}{}{}│", left, " ".repeat(gap), right)
}

fn render_prompt_line(inner_width: usize, lesson: &str, typed: &str) -> String {
    let lesson_width = display_width(lesson);
    let left = inner_width.saturating_sub(lesson_width) / 2;
    let right = inner_width.saturating_sub(left + lesson_width);
    let typed_len = typed.chars().count().min(lesson.chars().count());
    let consumed: String = lesson.chars().take(typed_len).collect();
    let remaining: String = lesson.chars().skip(typed_len).collect();
    format!(
        "│{}{}{}{}│",
        " ".repeat(left),
        consumed,
        if remaining.is_empty() {
            String::new()
        } else {
            format!("{}{}{}", BOLD, remaining, RESET)
        },
        " ".repeat(right)
    )
}

fn render_error_line(inner_width: usize, lesson: &str, typed: &str) -> String {
    let correct = typed
        .chars()
        .zip(lesson.chars())
        .take_while(|(a, b)| a == b)
        .count();
    let suffix: String = typed.chars().skip(correct).collect();
    if suffix.is_empty() {
        return blank_line(inner_width);
    }
    let width = display_width(&suffix);
    let left = inner_width.saturating_sub(width) / 2;
    let right = inner_width.saturating_sub(left + width);
    format!(
        "│{}{}{}{}{}│",
        " ".repeat(left),
        ITALIC,
        suffix,
        RESET,
        " ".repeat(right)
    )
}

fn render_metric_line(inner_width: usize, target: u16, avg: u64, last: u64) -> String {
    format_metric_line(inner_width, target, avg, last, None)
}

fn render_metric_line_with_suffix(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: &str,
) -> String {
    format_metric_line(inner_width, target, avg, last, Some(suffix))
}

fn render_acc_line(inner_width: usize, target: u16, avg: u64, last: u64) -> String {
    format_acc_line(inner_width, target, avg, last, None)
}

fn render_acc_line_with_suffix(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: &str,
) -> String {
    format_acc_line(inner_width, target, avg, last, Some(suffix))
}

fn format_metric_line(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: Option<&str>,
) -> String {
    let base = format!(
        "  need >= {:>3}WPM,   avg. {:>3}WPM,   last{:>4}WPM",
        target, avg, last
    );
    wrap_inner(inner_width, &base, suffix)
}

fn format_acc_line(
    inner_width: usize,
    target: u16,
    avg: u64,
    last: u64,
    suffix: Option<&str>,
) -> String {
    let base = format!(
        "  need >= {:>3}% Acc, avg. {:>3}% Acc, last{:>4}% Acc",
        target, avg, last
    );
    wrap_inner(inner_width, &base, suffix)
}

fn wrap_inner(inner_width: usize, left_text: &str, suffix: Option<&str>) -> String {
    match suffix {
        Some(suffix) => {
            let used = display_width(left_text) + display_width(suffix);
            let gap = inner_width.saturating_sub(used);
            format!("│{}{}{}│", left_text, " ".repeat(gap), suffix)
        }
        None => {
            let gap = inner_width.saturating_sub(display_width(left_text));
            format!("│{}{}│", left_text, " ".repeat(gap))
        }
    }
}

fn render_keyboard(layout: &Layout, ortho: bool, cat: bool, inner_width: usize) -> Vec<String> {
    let rows = if ortho {
        render_ortho_keyboard(layout)
    } else {
        render_staggered_keyboard(layout)
    };

    let left_pad = if cat { 5 } else { 0 };
    rows.into_iter()
        .enumerate()
        .map(|(idx, row)| {
            if cat {
                let suffix = match idx {
                    2 => Some("          /\\_/\\\\        "),
                    3 => Some("        >(•༝• )<      "),
                    4 => Some("         |    \\       "),
                    5 => Some("          || |  )      "),
                    6 => Some("          ll-l-//      "),
                    _ => None,
                };
                let prefix = format!("{}{}", " ".repeat(left_pad), row);
                wrap_inner(inner_width, &prefix, suffix)
            } else {
                let row_width = display_width(&row);
                let pad = inner_width.saturating_sub(row_width) / 2;
                let right = inner_width.saturating_sub(pad + row_width);
                format!("│{}{}{}│", " ".repeat(pad), row, " ".repeat(right))
            }
        })
        .collect()
}

fn render_staggered_keyboard(layout: &Layout) -> Vec<String> {
    vec![
        STAGGERED_TOP.to_string(),
        format!("│ {} │", layout.row1.join(" │ ")),
        STAGGERED_MID_1.to_string(),
        format!(" │ {} │", layout.row2.join(" │ ")),
        format!(" {}", STAGGERED_MID_2),
        format!("  │ {} │", layout.row3.join(" │ ")),
        format!("  {}", STAGGERED_BOTTOM),
    ]
}

fn render_ortho_keyboard(layout: &Layout) -> Vec<String> {
    let mut row2: Vec<&str> = layout.row2.to_vec();
    row2.push("△");
    let mut row3: Vec<&str> = layout.row3.to_vec();
    row3.push("△");
    row3.push("△");

    vec![
        ORTHO_TOP.to_string(),
        format!("│ {} │", layout.row1.join(" │ ")),
        ORTHO_MID.to_string(),
        format!("│ {} │", row2.join(" │ ")),
        ORTHO_MID.to_string(),
        format!("│ {} │", row3.join(" │ ")),
        ORTHO_BOTTOM.to_string(),
    ]
}

